int A = 5;  // Binary: 0101
int B = 3;  // Binary: 0011

/* Definition: Result bit is 1 only if input bits differ. */
int C = A ^ B; // Result: 6 (Binary: 0110)

/* Property 1: Identity (XOR with zero) */
int D = A ^ 0; // D == A

/* Property 2: Inversion (XOR with self) */
int E = A ^ A; // E == 0

/* Usage: Toggling bits using a mask */
int data = 0b10101010;
int mask = 0b00001111; // Toggle lower nibble

int toggled = data ^ mask;
// toggled == 0b10100101
